    await frame(); swatter.style.transition="transform .45s cubic-bezier(.3,1.2,.5,1)"; sPose(px,py,ang+38); await sleep(480);
    swatter.style.transition="transform .09s cubic-bezier(.6,0,1,1)"; sPose(px,py,ang); await sleep(95);
